import{_ as p,a0 as i,w as l,s as n,ao as d,I as r,x as e,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"成为一名软件开发者你应该学习哪种语言？ | LCTT x X-CMD","titleTemplate":false,"description":"成为一名软件开发者你应该学习哪种语言？ | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"成为一名软件开发者你应该学习哪种语言？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"成为一名软件开发者你应该学习哪种语言？ | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170616 Do you have what it takes to be a software developer","title":"成为一名软件开发者你应该学习哪种语言？","tag":"201707","desc":""},"relativePath":"201707/20170616 Do you have what it takes to be a software developer.md","filePath":"[post].md"}'),u={name:"201707/20170616 Do you have what it takes to be a software developer.md"};function w(f,t,v,m,T,b){const a=i("Link");return l(),n("div",null,[t[13]||(t[13]=d('<h1 id="成为一名软件开发者你应该学习哪种语言" tabindex="-1">成为一名软件开发者你应该学习哪种语言？ <a class="header-anchor" href="#成为一名软件开发者你应该学习哪种语言" aria-label="Permalink to “成为一名软件开发者你应该学习哪种语言？”">​</a></h1><p><img src="https://www.linuxcareer.com/images/software_developer_skills.jpg" alt=""></p><p>应用程序的领域在不断发展。底层的 Linux 做了很多工作，而且还在继续，但是在过去几年里，应用程序领域开始增长。在这种情况下，开发人员使用哪种语言构建这些应用程序？简而言之，要看情况，我知道这个说法没啥稀奇的。但是，通过我们拥有的数据，我们可以确定哪些语言领先。</p><p>站在山顶的语言是 Java。它已经出现在开源软件领域 15 年以上，但它并不是一直在顶峰。在早期，我们没有看到那么多对 java 开发者感兴趣的，但现在情况已经改变了。它是目前应用领域的权威领导者。虽然这个数字在过去六个季度没有明显增长，但其整体数量却令人印象深刻。平均而言，关注于开源软件的公司发布的职位中有超过 1/3 的职位要求 Java 技能。这对几年前没有在榜单上出现的语言而言是一个非凡的成就。而且，由于它在 Android 中的大量使用，未来这个数字进一步增加也并不奇怪。</p><p>在应用程序领域中使用的另一种语言是 C++。虽然它的数量不能与 Java 竞争，但它仍然在这个领域占据了很大的市场份额。而且每 3 个招聘中有一个要求 Java，C++ 则是每 4 个中有一个要求它。与 Java 非常类似，其数量在过去六个季度中保持相对稳定。C++ 一直被大量使用，即使 Java 已经取代它，它仍然是一种高度相关的语言。</p><p>进入到网络应用领域，多年来一直在城头变幻大王旗。在早期，大多数 Web 程序毫无疑问地选择使用 PHP 开发。正如之前关于脚本的文章所讨论的，这几年来已经发生了变化。在过去几年中，PHP 的使用似乎有所恶化。在过去一年半的时间里，已经急剧下降了 30％ 以上。这是一个令人震惊的数字，只有时间才能告诉我们趋势是否持续。</p><p>最初打破 PHP 领导地位的是 Ruby on Rails。多年来，我看到公司们和开发者们进行了这一转型。Ruby on Rails 经历了一段时间，在这个时期它是这个领域的首选语言。然而，从我们收集的数字来看，它的光泽似乎已经失去了一点。虽然没有像 PHP 这样的衰退，但其数量一直保持相对平稳，它曾经有过的增长似乎停滞不前。</p><p>目前在网络应用程序领域的王者似乎是 Javascript。它获得了最大的总数。虽然它的数量保持平坦，这很像 Ruby on Rails，但它已经吸引了更多的观众。平均来说，过去六个季度，公司在分析的 10,000 份工作清单中有 1,500 份需要 Javascript 技能。这比 PHP 或 Ruby on Rails 多了 70％。</p><p>随着 PHP 的衰落以及 Ruby on Rails 和 Javascript 停滞不前，是谁在 Web 程序领域保持增长呢？这个群体的突出者似乎是 Golang。它在 2007 年由 Google 内的几位开发人员创建，似乎这种语言开始获得更广泛的受众群体。虽然与我们讨论的其它三个的总数相比不多，但看起来这一年半以来增长了 50％。如果这种趋势继续下去，那将是非常有趣的。在我看来，我预计我们会继续看到 Golang 挤占 其它三个的群体份额。</p><p>如往常一样，我们会监测这些语言的各种前进方向，以观察市场趋势。而且，榜单的任何新进入者都会被密切关注。这是一个令人兴奋和动态的发展领域。一个会提供随时间不断变化的结果。</p><hr>',11)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(a,{href:"https://www.linuxcareer.com/do-you-have-what-it-takes-to-be-a-software-developer"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.linuxcareer.com/do-you-have-what-it-takes-to-be-a-software-developer",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),o(a,{href:"https://www.linuxcareer.com/do-you-have-what-it-takes-to-be-a-software-developer"},{default:s(()=>[...t[2]||(t[2]=[e("Brent Marinaccio",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),o(a,{href:"https://github.com/geekpi"},{default:s(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),o(a,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创编译，",-1)),o(a,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const _=p(u,[["render",w]]);export{P as __pageData,_ as default};
